v"]=velocity;fragment["w"]=angular;if(energy>strongestEnergy){strongestEnergy=energy;strongest=hit;}if(speed<-.5){emit(owner,controller,actorId,id+":"+otherId,"impact",time,hit["point"].AsVector3(),normal,relative,energy);if(states.ContainsKey(otherId)){var target=states[otherId].AsGodotDictionary();var impacts=Get(target,"structure_pending_impacts",new GArray()).AsGodotArray();target["structure_pending_impacts"]=impacts;impacts.Add(new Settings{["point"]=hit["point"],["normal"]=-normal,["energy"]=energy});}}if(tangent.Length()>1&&Math.Abs(speed)<.5)emit(owner,controller,actorId,id+":"+otherId,"scrape",time,hit["point"].AsVector3(),normal,tangent,.5*mass*tangent.LengthSquared());}angular*=(float)Math.Exp(-(config["angular_damping"].AsDouble()+(hits.Count>0?config["friction"].AsDouble()*8:0))*h);double sleep=hits.Count>0&&velocity.Length()<.12&&angular.Length()<.2?Get(fragment,"sleep",0).AsDouble()+h:0;fragment["sleep"]=sleep;if(sleep>.6){velocity=Vector3.Zero;angular=Vector3.Zero;}fragment["v"]=velocity;fragment["w"]=angular;fragment["pose"]=pose;_collision.place(world,id,pose,collision);if(Get(values,"debris_secondary",false).AsBool()&&strongestEnergy>Get(values,"debris_secondary_energy",10).AsDouble()&&Get(fragment,"depth",0).AsInt32()<Get(values,"debris_depth",2).AsInt32()&&radius>Get(values,"debris_min_size",.08).AsDouble()*2){var children=secondary(owner,controller,entry,fragment,strongest,strongestEnergy,time);if(children.Count>0)splits.Add(new Settings{["owner"]=actorId,["parent"]=fragment,["children"]=children});}
